def find_frames(grid):
    """Find rectangular frames (hollow rectangles)"""
    h, w = len(grid), len(grid[0])
    frames = []

    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] == 3:
                # Find how far this extends
                max_r = r1
                max_c = c1
                while max_r + 1 < h and grid[max_r + 1][c1] == 3:
                    max_r += 1
                while max_c + 1 < w and grid[r1][max_c + 1] == 3:
                    max_c += 1

                # Check if it's a frame (border with interior)
                h_size = max_r - r1 + 1
                w_size = max_c - c1 + 1
                if h_size >= 3 and w_size >= 3:
                    is_frame = True
                    # Check top and bottom rows are all 3s
                    for cc in range(c1, max_c + 1):
                        if grid[r1][cc] != 3 or grid[max_r][cc] != 3:
                            is_frame = False
                    # Check left and right columns are all 3s
                    for rr in range(r1, max_r + 1):
                        if grid[rr][c1] != 3 or grid[rr][max_c] != 3:
                            is_frame = False

                    # Check interior is empty (or not 3)
                    if is_frame:
                        has_interior_3 = False
                        for rr in range(r1 + 1, max_r):
                            for cc in range(c1 + 1, max_c):
                                if grid[rr][cc] == 3:
                                    has_interior_3 = True
                                    break
                            if has_interior_3:
                                break

                        if not has_interior_3:
                            frames.append((r1, c1, max_r, max_c))

    return frames

